import math
from fractions import Fraction

def solve():
    solutions = []
    for k in range(-1000, 1001):
        if k == 0:
            continue
        x_frac = Fraction(88, k)
        k1 = math.floor(x_frac)
        k2 = math.floor(x_frac * k1)
        k3 = math.floor(x_frac * k2)
        val = x_frac * k3
        if val == 88:
            solutions.append(x_frac / 22)
    return sorted(list(set(solutions)))

print(solve())

def check():
    solutions = []
    for k in range(1, 89):
        k1 = 88 // k
        k2 = (88 * k1) // k
        k3_prime = (88 * k2) // k
        if k3_prime == k:
            solutions.append(k)
    return solutions

print(check())
